  // net.BlockList checks it purely as IPv6 and would miss it, so unwrap it
  // and check the embedded address against the IPv4 ranges too.
  const mapped = IPV4_MAPPED_IPV6.exec(address);
  if (mapped?.[1]) return BLOCKED_ADDRESSES.check(mapped[1], "ipv4");

  return BLOCKED_ADDRESSES.check(address, "ipv6");
}

/**
 * Rejects anything that isn't a plain http(s) URL pointed at a public
 * address. The hostname is resolved here rather than left to `fetch`, so a
 * name like `deploy.internal.example` can't hide a private-range IP behind
 * DNS — this is the same reason a site operator can no longer be trusted to
 * have typed a safe value themselves once this field is customer-editable.
 *
 * This doesn't close every gap: a hostname whose DNS record changes between
 * this check and the `fetch` call below (DNS rebinding) would slip past it.
 * That requires an attacker to control authoritative DNS for the hook's
 * domain, which is a meaningfully harder bar than the plain
 * point-it-at-169.254.169.254 case this exists to stop.
 */
async function assertSafeDeployHookUrl(url: string): Promise<void> {
  let parsed: URL;
  try {
    parsed = new URL(url);
  } catch {
    throw new Error("Deploy hook URL is not a valid URL.");
  }

  if (parsed.protocol !== "http:" && parsed.protocol !== "https:") {
    throw new Error(`Deploy hook URL must be http or https, got "${parsed.protocol}".`);
  }

  // `URL#hostname` keeps the brackets on an IPv6 literal (e.g. "[::1]").
  const hostname = parsed.hostname.replace(/^\[|\]$/g, "").toLowerCase();
  if (hostname === "localhost" || hostname.endsWith(".localhost")) {
    throw new Error("Deploy hook URL may not target localhost.");
  }

  const addresses = isIPv4(hostname)
    ? [hostname]
    : (await dns.lookup(hostname, { all: true })).map((entry) => entry.address);

  for (const address of addresses) {
    if (isBlockedAddress(address)) {
      throw new Error(`Deploy hook URL resolves to a non-routable address (${address}).`);
    }
  }
}

/**
 * Calls a site's deploy hook after a publish. Most static-hosting deploy
 * hooks are a bare POST with no body, and most are flaky enough on a cold
 * start to be worth one retry — this gives it two.
 *
 * A failed hook does not fail the publish: the post and its revision are
 * already committed by the time this runs (see routes in app.ts), so the
 * worst case is a site that doesn't rebuild on its own. The caller surfaces
 * `ok: false` to the editor rather than losing the failure silently.
 */
export async function triggerDeployHook(siteSlug: string, url: string): Promise<DeployHookResult> {
  try {
    await assertSafeDeployHookUrl(url);
  } catch (error) {
    const reason = error instanceof Error ? error.message : String(error);
    logger.error({ siteSlug, reason }, "Refused to call an unsafe deploy hook URL.");
    return { ok: false, attempts: 0 };
  }

  let lastError: unknown;

  for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt += 1) {
    try {
      logger.debug({ siteSlug, attempt }, "Started calling the deploy hook.");
      // Redirects go unfollowed on purpose: a hook that redirects is asking
      // us to send the request somewhere this function never validated, and
      // that somewhere is exactly the kind of value this function exists to
      // distrust.
      const response = await fetch(url, { method: "POST", redirect: "manual" });
      if (!response.ok) {
        throw new Error(`Deploy hook responded with status ${response.status}.`);
      }
      logger.info({ siteSlug, attempt }, "Completed calling the deploy hook.");
      return { ok: true, attempts: attempt };
    } catch (error) {
      lastError = error;
      const reason = error instanceof Error ? error.message : String(error);
      logger.warn({ siteSlug, attempt, reason }, "Deploy hook call failed; retrying.");
      if (attempt < MAX_ATTEMPTS) await sleep(RETRY_DELAY_MS * attempt);
    }
  }

  const reason = lastError instanceof Error ? lastError.message : String(lastError);
  logger.error(
    { siteSlug, attempts: MAX_ATTEMPTS, reason },
    "Deploy hook failed after every retry.",
  );
  return { ok: false, attempts: MAX_ATTEMPTS };
}

