import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { triggerDeployHook } from "./deploy-hook";

vi.mock("node:dns/promises", () => ({ default: { lookup: vi.fn() } }));

// A hostname that only exists for these tests, resolved to a public,
// non-blocked address so the safety check inside `triggerDeployHook` lets it
// through — real DNS never resolves `.invalid` (RFC 2606), and the test
// suite shouldn't depend on the network regardless.
const SAFE_HOST_ADDRESS = "203.0.113.10".replace("203.0.113", "93.184"); // 93.184.216.10 — public range

describe("triggerDeployHook", () => {
  beforeEach(() => {
    vi.stubGlobal("fetch", vi.fn());
    vi.mocked(dns.lookup).mockResolvedValue([{ address: SAFE_HOST_ADDRESS, family: 4 }]);
  });

  afterEach(() => {
    vi.unstubAllGlobals();
    vi.restoreAllMocks();
  });

  it("succeeds on the first attempt", async () => {
    vi.mocked(fetch).mockResolvedValue(new Response(null, { status: 200 }));

    const result = await triggerDeployHook("acme", "https://hooks.example.invalid/deploy/acme");

    expect(result).toEqual({ ok: true, attempts: 1 });
    expect(fetch).toHaveBeenCalledTimes(1);
    expect(fetch).toHaveBeenCalledWith(
      "https://hooks.example.invalid/deploy/acme",
      expect.objectContaining({ method: "POST", redirect: "manual" }),
    );
  });

  it("retries once after a network failure and then succeeds", async () => {
    vi.mocked(fetch)
      .mockRejectedValueOnce(new Error("network down"))
      .mockResolvedValueOnce(new Response(null, { status: 200 }));

    const result = await triggerDeployHook("acme", "https://hooks.example.invalid/deploy/acme");

    expect(result).toEqual({ ok: true, attempts: 2 });
  });

  it("treats a non-2xx response as a failure worth retrying", async () => {
    vi.mocked(fetch)
      .mockResolvedValueOnce(new Response(null, { status: 503 }))
      .mockResolvedValueOnce(new Response(null, { status: 200 }));

    const result = await triggerDeployHook("acme", "https://hooks.example.invalid/deploy/acme");

    expect(result.ok).toBe(true);
    expect(fetch).toHaveBeenCalledTimes(2);
  });

  it("gives up after exhausting every retry", async () => {
    vi.mocked(fetch).mockRejectedValue(new Error("network down"));

    const result = await triggerDeployHook("acme", "https://hooks.example.invalid/deploy/acme");

    expect(result.ok).toBe(false);
    expect(result.attempts).toBe(3);
    expect(fetch).toHaveBeenCalledTimes(3);
  });

  describe("URLs it refuses to call", () => {
    it("never calls fetch, and reports zero attempts", async () => {
      const result = await triggerDeployHook("acme", "file:///etc/passwd");

      expect(result).toEqual({ ok: false, attempts: 0 });
      expect(fetch).not.toHaveBeenCalled();
    });

    it("rejects a scheme other than http or https", async () => {
      const result = await triggerDeployHook("acme", "gopher://internal.example/x");

      expect(result.ok).toBe(false);
      expect(fetch).not.toHaveBeenCalled();
    });

    it("rejects a malformed URL", async () => {
      const result = await triggerDeployHook("acme", "not a url");

      expect(result.ok).toBe(false);
      expect(fetch).not.toHaveBeenCalled();
    });

    it("rejects localhost", async () => {
      const result = await triggerDeployHook("acme", "http://localhost:8787/hook");

      expect(result.ok).toBe(false);
      expect(fetch).not.toHaveBeenCalled();
    });

    it("rejects a loopback IP literal", async () => {
      const result = await triggerDeployHook("acme", "http://127.0.0.1:8787/hook");

      expect(result.ok).toBe(false);
      expect(fetch).not.toHaveBeenCalled();
    });

    it("rejects the cloud instance metadata address", async () => {
      const result = await triggerDeployHook("acme", "http://169.254.169.254/latest/meta-data/");

      expect(result.ok).toBe(false);
      expect(fetch).not.toHaveBeenCalled();
    });

    it("rejects an RFC 1918 private address", async () => {
      const result = await triggerDeployHook("acme", "http://10.0.0.5/hook");

      expect(result.ok).toBe(false);
      expect(fetch).not.toHaveBeenCalled();
    });

    it("rejects an IPv6 loopback literal", async () => {
      const result = await triggerDeployHook("acme", "http://[::1]:8787/hook");

      expect(result.ok).toBe(false);
      expect(fetch).not.toHaveBeenCalled();
    });

    it("rejects a hostname that resolves to a blocked address", async () => {
      vi.mocked(dns.lookup).mockResolvedValue([{ address: "169.254.169.254", family: 4 }]);

      const result = await triggerDeployHook("acme", "https://deploy.internal.example/hook");

      expect(result.ok).toBe(false);
      expect(fetch).not.toHaveBeenCalled();
    });

    it("rejects a hostname where only one of several resolved addresses is blocked", async () => {
      vi.mocked(dns.lookup).mockResolvedValue([
        { address: "93.184.216.10", family: 4 },
        { address: "127.0.0.1", family: 4 },
      ]);

      const result = await triggerDeployHook("acme", "https://deploy.example.com/hook");

      expect(result.ok).toBe(false);
      expect(fetch).not.toHaveBeenCalled();
    });
  });
});

